/**
 * Loads the built bundle the way Obsidian does, to catch anything that only
 * shows up at load time: a syntax error, a top-level throw, a missing export,
 * an unbundled dependency.
 *
 * The Obsidian API is stubbed just enough to require the bundle and construct
 * the plugin. This is not a substitute for opening the plugin in Obsidian — it
 * only proves the artifact is loadable.
 *
 * Run with `npm run smoke` after `npm run build`.
 */
const Module = require('module');
const fs = require('fs');
const os = require('os');
const path = require('path');

// --- the smallest Obsidian that will do ---
class Component {}
class Plugin extends Component {
	constructor(app, manifest) {
		super();
		this.app = app;
		this.manifest = manifest;
	}
	addCommand(command) { return command; }
	addRibbonIcon() { return { addClass() {} }; }
	addSettingTab() {}
	registerEvent() {}
	registerInterval() {}
	registerDomEvent() {}
	async loadData() { return {}; }
	async saveData() {}
}
class Modal extends Component { constructor(app) { super(); this.app = app; } setTitle() {} open() {} close() {} }
class PluginSettingTab extends Component { constructor(app, plugin) { super(); this.app = app; this.plugin = plugin; } }
class Setting {
	setName() { return this; }
	setDesc() { return this; }
	setHeading() { return this; }
	addText() { return this; }
	addToggle() { return this; }
	addDropdown() { return this; }
}

const obsidianStub = {
	Component, Plugin, Modal, PluginSettingTab, Setting,
	TFile: class {}, TFolder: class {}, TAbstractFile: class {},
	MarkdownView: class extends Component {}, Notice: class {},
	normalizePath: (p) => p.replace(/\/+/g, '/').replace(/^\//, ''),
	requestUrl: async () => ({ status: 200, json: {} }),
	requireApiVersion: () => true,
	debounce: (fn) => fn,
	setIcon: () => {},
	moment: () => ({ format: () => '2026-01-01' }),
};

const load = Module._load;
Module._load = function (request, parent, isMain) {
	if (request === 'obsidian') return obsidianStub;
	return load.call(this, request, parent, isMain);
};

// --- run the checks ---
let failures = 0;
const ok = (label) => console.log(`ok   ${label}`);
const bad = (label, detail) => { failures++; console.log(`FAIL ${label}\n     ${detail}`); };

const bundlePath = path.resolve('main.js');
if (!fs.existsSync(bundlePath)) {
	console.log('FAIL main.js is missing — run `npm run build` first');
	process.exit(1);
}

// package.json says "type": "module", so Node would read main.js as ESM.
// Obsidian loads it as CommonJS; copying to .cjs reproduces that.
const copy = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'rt-smoke-')), 'bundle.cjs');
fs.copyFileSync(bundlePath, copy);

let exported;
try {
	exported = require(copy);
	ok('main.js loads without throwing');
} catch (error) {
	bad('main.js loads without throwing', error.stack);
	process.exit(1);
}

const PluginClass = exported.default ?? exported;
if (typeof PluginClass !== 'function') {
	bad('default export is a class', `got ${typeof PluginClass}`);
} else {
	ok('default export is a class');
	PluginClass.prototype instanceof Plugin
		? ok('default export extends Plugin')
		: bad('default export extends Plugin', 'it does not');
}

try {
	const instance = new PluginClass({}, require(path.resolve('manifest.json')));
	const required = ['onload', 'onunload', 'loadSettings', 'saveSettings'];
	const missing = required.filter((name) => typeof instance[name] !== 'function');
	missing.length === 0
		? ok('plugin instantiates with its lifecycle methods')
		: bad('plugin instantiates with its lifecycle methods', `missing ${missing.join(', ')}`);
} catch (error) {
	bad('plugin instantiates', error.message);
}

const source = fs.readFileSync(bundlePath, 'utf8');
source.includes('THIS IS A GENERATED/BUNDLED FILE BY ESBUILD')
	? ok('build banner present')
	: bad('build banner present', 'the directory expects it on a bundled main.js');
source.includes('//# sourceMappingURL=')
	? bad('no inline sourcemap', 'found one — did you build with `npm run dev`?')
	: ok('no inline sourcemap');
/require\((["'])(?!obsidian|electron|@codemirror|@lezer)[^)]*\1\)/.test(source)
	? bad('everything is bundled', 'the bundle still requires something at runtime')
	: ok('everything is bundled');

console.log(failures === 0 ? '\nSMOKE PASS\n' : `\n${failures} failure(s)\n`);
process.exit(failures === 0 ? 0 : 1);
